  }

  #pruneAt(nowMs) {
    let removed = 0;
    for (const [key, entry] of this.#entries) {
      if (IdempotencyGuard.#isExpired(entry, nowMs)) {
        this.#entries.delete(key);
        removed += 1;
      }
    }
    return removed;
  }
}
